-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create table public.activity_posts (
  id uuid default gen_random_uuid() not null,
  car_id uuid,
  author_id uuid not null,
  title text,
  intro text,
  body jsonb default '[]'::jsonb not null,
  video_url text,
  published_at timestamp with time zone default now(),
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  search_text text generated always as (public.activity_post_search_text(body)) stored,
  draft_key uuid,
  draft_archived_at timestamp with time zone,
  publish_operation_id uuid
);

alter table public.activity_posts enable row level security;

-- Comments
comment on column public.activity_posts.car_id is 'Optional since W-5. A post must be about a car, a tagged part, or both — see the trigger below.';
comment on column public.activity_posts.title is 'Optional since the 2026-09 direction: a quick post is a photo and a caption. Readers use postHeadline() rather than assuming a value.';
comment on column public.activity_posts.draft_archived_at is 'Older duplicate drafts retained in place during the durable-draft upgrade; excluded from the active composer.';
comment on column public.activity_posts.publish_operation_id is 'Client-stable UUID used to reconcile a publish whose response was lost.';

-- Constraints
alter table public.activity_posts add constraint activity_posts_author_id_fkey FOREIGN KEY (author_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
alter table public.activity_posts add constraint activity_posts_car_id_fkey FOREIGN KEY (car_id) REFERENCES public.cars(id) ON DELETE CASCADE;
alter table public.activity_posts add constraint activity_posts_pkey PRIMARY KEY (id);
alter table public.activity_posts add constraint activity_posts_text_bounds CHECK (char_length(title) >= 1 AND char_length(title) <= 160 AND char_length(COALESCE(intro, ''::text)) <= 2000);
alter table public.activity_posts add constraint guard_post_has_subject TRIGGER DEFERRABLE INITIALLY DEFERRED;

-- Indexes
CREATE INDEX activity_posts_author_idx ON public.activity_posts USING btree (author_id);
CREATE INDEX activity_posts_author_published_idx ON public.activity_posts USING btree (author_id, published_at DESC, id DESC) WHERE (published_at IS NOT NULL);
CREATE INDEX activity_posts_car_idx ON public.activity_posts USING btree (car_id);
CREATE INDEX activity_posts_car_published_idx ON public.activity_posts USING btree (car_id, published_at DESC, id DESC) WHERE (published_at IS NOT NULL);
CREATE INDEX activity_posts_feed_idx ON public.activity_posts USING btree (published_at DESC, id DESC) WHERE (published_at IS NOT NULL);
CREATE UNIQUE INDEX activity_posts_one_active_draft_idx ON public.activity_posts USING btree (car_id, author_id) WHERE ((published_at IS NULL) AND (draft_archived_at IS NULL));
CREATE UNIQUE INDEX activity_posts_publish_operation_idx ON public.activity_posts USING btree (author_id, publish_operation_id) WHERE (publish_operation_id IS NOT NULL);
CREATE INDEX activity_posts_published_car_idx ON public.activity_posts USING btree (published_at, car_id) WHERE (published_at IS NOT NULL);
CREATE INDEX activity_posts_published_idx ON public.activity_posts USING btree (published_at DESC) WHERE (published_at IS NOT NULL);
CREATE INDEX activity_posts_search_doc_trgm_idx ON public.activity_posts USING gin (public.post_search_doc(title, intro, search_text) public.gin_trgm_ops) WHERE (published_at IS NOT NULL);
CREATE INDEX activity_posts_search_text_trgm_idx ON public.activity_posts USING gin (search_text public.gin_trgm_ops);
CREATE INDEX activity_posts_title_trgm_idx ON public.activity_posts USING gin (title public.gin_trgm_ops);

-- Grants
grant all on table public.activity_posts to anon;
grant all on table public.activity_posts to authenticated;
